enum OnboardingState: Int {
    case step0
    case step1
    case step2
    case completed

    mutating func next() {
        if let nextState = OnboardingState(rawValue: self.rawValue + 1) {
            self = nextState
        } else {
            self = .completed
        }
    }
}

