                    .padding()
                    .background(Color.blue)
                    .cornerRadius(10)
            }
        }
    }
}

struct OnboardingView<Content: View>: View {
    @Binding var onboardingState: OnboardingState
    var hasCompletedOnboarding: Bool
    var content: () -> Content
    var highlightRect: CGRect

    var body: some View {
        ZStack {
            content()
                .blur(radius: onboardingState != .completed ? 10 : 0)
                .disabled(onboardingState != .completed)

            if onboardingState != .completed {
                Color.black.opacity(0.6).edgesIgnoringSafeArea(.all)
                RoundedRectangle(cornerRadius: 12)
                    .stroke(Color.clear, lineWidth: 4)
                    .background(RoundedRectangle(cornerRadius: 12).fill(Color.clear))
                    .frame(width: highlightRect.width, height: highlightRect.height)
                    .position(x: highlightRect.midX, y: highlightRect.midY)
                OnboardingOverlay(message: onboardingMessage, onNext: {

                    onboardingState.next()
                    if onboardingState == .completed {
                        UserDefaults.standard.set(true, forKey: "hasCompletedOnboarding")

                    }
                })
            }
        }
        .onAppear {

        }
        .onDisappear {

        }
    }

    private var onboardingMessage: String {
        switch onboardingState {
        case .step0: return "Welcome to the app! Click the button to proceed."
        case .step1: return "This button toggles states. Click again."
        case .step2: return "One more time! Click the button."
        case .completed: return ""
        }
    }
}

